class Policy:
    # Changed: prioritize unsolved tasks over solved ones, with round-robin fallback
    def __init__(self):
        self.scores = {}  # task_id -> best score seen
        self.attempts = {}  # task_id -> number of times picked

    def pick(self, keys, round_index):
        # Filter to tasks we haven't solved yet (score < 1.0)
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            # All solved in this shard, just round-robin
            return keys[round_index % len(keys)]

        # Among unsolved, prefer ones we've tried least (exploration)
        # and ones with lower scores (more room for improvement)
        def priority(k):
            attempts = self.attempts.get(k, 0)
            score = self.scores.get(k, 0)
            # Lower attempts and lower scores get higher priority
            return (attempts, score)

        return min(unsolved, key=priority)

    def record(self, task_id, score):
        # Keep best score seen
        if task_id not in self.scores or score > self.scores[task_id]:
            self.scores[task_id] = score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
