class Policy:
    # Changed: Use Thompson sampling with Beta priors to better balance exploration of unknown tasks
    # and exploitation of known low scores, while avoiding solved tasks when alternatives exist.
    def __init__(self):
        self.scores = {}
        self.attempts = {}

    def pick(self, keys, round_index):
        # Filter out solved tasks if there are alternatives
        unsolved = [k for k in keys if self.scores.get(k, 0) < 1.0]
        if not unsolved:
            unsolved = keys  # all solved, just pick any

        # Thompson sampling: sample from Beta(alpha, beta) where alpha = successes, beta = failures
        # For unknown tasks, use a prior that encourages exploration (Beta(1,1) = uniform)
        def thompson_key(k):
            score = self.scores.get(k, None)
            attempts = self.attempts.get(k, 0)

            if score is None:
                # Unknown task: sample from uniform prior, but add small bonus for being unknown
