                beta = (1 - score) * attempts + 1
                # Sample from Beta distribution - lower sample means more likely to improve
                return random.betavariate(alpha, beta)

        return min(unsolved, key=thompson_key)

    def record(self, task_id, score):
        self.scores[task_id] = score
        self.attempts[task_id] = self.attempts.get(task_id, 0) + 1
